// Healthcare custom scripts
frappe.provide("frappe.healthcare");

// Init for healthcare application
frappe.healthcare.init = function() {
    console.log("Healthcare application initialized");
    
    // Apply steel blue theme across healthcare pages
    if (document.body) {
        const styleElement = document.createElement('style');
        styleElement.textContent = `
            .healthcare-header {
                background-color: #4682b4 !important;
                color: white !important;
            }
            .healthcare-button {
                background-color: #4682b4 !important;
                color: white !important;
            }
            .healthcare-page {
                background-color: #f5f7fa !important;
            }
        `;
        document.head.appendChild(styleElement);
    }
};

// Initialize on document ready
$(document).ready(function() {
    frappe.healthcare.init();
});
